/* Reset margins and paddings */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Full screen background (NOT darkened, original bg.png) */
body {
    background-image: url('data:image/png;base64,');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    min-height: 100vh;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: #ffffff;
    display: flex;
    justify-content: center;
    align-items: center;
    overflow-x: hidden;
}

/* Page system container */
.page-container {
    width: 100%;
    max-width: 1100px;
    padding: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
}

.page {
    display: none;
    width: 100%;
    animation: fadeIn 0.3s ease-in-out;
}

.page.active {
    display: block;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* 3x6 Grid Layout for Home Page */
.grid-3x6 {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 16px;
    width: 100%;
    max-width: 950px;
    margin: 0 auto;
}

/* Grid Box styling - Dark Wooden Brown */
.grid-box {
    aspect-ratio: 1;
    border: 1px solid #ffffff;
    background-color: #5c3a21; /* Rich dark wooden brown */
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 2.2rem;
    font-weight: 700;
    font-family: sans-serif;
    color: #f0e6d2;
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
    border-radius: 6px;
    user-select: none;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.4);
}

.grid-box:hover {
    transform: translateY(-4px);
    background-color: #6d4629;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.6);
}

/* Empty grid slots (cells 16, 17, 18) */
.grid-box.empty {
    background-color: rgba(92, 58, 33, 0.3);
    border: 1px dashed rgba(255, 255, 255, 0.4);
    cursor: default;
    box-shadow: none;
}
.grid-box.empty:hover {
    transform: none;
    background-color: rgba(92, 58, 33, 0.3);
    box-shadow: none;
}

/* Quiz Page Layout */
.quiz-page {
    background: rgba(45, 28, 15, 0.92); /* Translucent dark wooden panel */
    border: 1px solid #ffffff;
    border-radius: 12px;
    padding: 35px;
    width: 100%;
    max-width: 850px;
    margin: 0 auto;
    min-height: 520px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.6);
}

/* Top Section: Question (Center Top) */
.quiz-top {
    text-align: center;
    padding: 10px 0 25px 0;
    flex: 0 0 auto;
}

.quiz-top h2 {
    font-size: 1.3rem;
    color: #d4a373;
    margin-bottom: 12px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
}

.quiz-question {
    font-size: 1.8rem;
    color: #ffffff;
    font-weight: 600;
    line-height: 1.4;
}

/* Lower 2/3rds Section: Choices */
.quiz-choices-container {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: 15px 0;
}

.choices-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

.choice-box {
    background-color: #5c3a21;
    border: 1px solid #ffffff;
    padding: 22px;
    border-radius: 6px;
    font-size: 1.2rem;
    font-weight: 600;
    color: #f0e6d2;
    text-align: center;
    cursor: pointer;
    transition: all 0.2s ease;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.3);
}

.choice-box:hover {
    background-color: #6d4629;
    transform: translateY(-2px);
    box-shadow: 0 6px 15px rgba(0, 0, 0, 0.5);
}

.choice-box.correct {
    background-color: #2d8a4e !important;
    border-color: #4ade80 !important;
    color: #ffffff !important;
}

.choice-box.incorrect {
    background-color: #991b1b !important;
    border-color: #f87171 !important;
    color: #ffffff !important;
}

/* Quiz Footer / Navigation */
.quiz-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 20px;
    border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.quiz-feedback-container {
    display: flex;
    flex-direction: column;
    gap: 6px;
    max-width: 550px;
}

.quiz-feedback {
    font-size: 1.2rem;
    font-weight: bold;
}

.quiz-explanation {
    font-size: 0.95rem;
    color: #e2e8f0;
    line-height: 1.4;
    font-style: italic;
}

.back-btn {
    background-color: transparent;
    color: #ffffff;
    border: 2px solid #ffffff;
    padding: 10px 25px;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.back-btn:hover {
    background-color: #ffffff;
    color: #5c3a21;
}
